fn solve(n: i8) -> Vec<char> {
    // Since n is guaranteed to be a three-digit number between 100 and 999,
    // we can safely convert it to string and extract its digits.
    let digits = n.to_string();
    let mut result = Vec::with_capacity(6);

    // Add the first three characters: 'A', 'B', 'C'
    result.push('A');
    result.push('B');
    result.push('C');

    // Append the digits of n to the vector
    // digits.chars() iterates over the chars in the string representation of n
    for ch in digits.chars() {
        result.push(ch);
    }

    // The vector should have exactly 6 characters now
    result
}